def compute(vars):
    pretax = vars["v1"]
    posttax = vars["v2"]
    if pretax == 0:
        return None
    change_ratio = (posttax - pretax) / pretax
    value = change_ratio * 100
    return {
        "value": value,
        "trace": {
            "pretax_profit": pretax,
            "posttax_profit": posttax,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
